'use strict';

/**
 * Generated by `aid infra gen`. Do not edit: the next run refuses to overwrite a
 * hand-edited file, and the construct carries no project fact to preserve.
 *
 * The AWS CDK spelling of `infra/generated/modules/batch`: one Fargate compute
 * environment and queue for the project, and one job definition per `batch`
 * deployment, whose command names the pipeline that deployment binds.
 *
 * Business inputs stay inputs: the image each job runs, the subnets and security groups
 * the task joins, its sizing, the ARN of each secret, and the id and ARN of an
 * already-created knowledge base arrive in `inputs`, never in this file.
 *
 * What it refuses, with the same sentence the HCL module puts in a `precondition`: a job
 * with no image, a deployment with no pipeline, a secret with no ARN, and a compute
 * environment with no subnet.
 */

const batch = require('aws-cdk-lib/aws-batch');
const bedrock = require('aws-cdk-lib/aws-bedrock');
const cdk = require('aws-cdk-lib');
const iam = require('aws-cdk-lib/aws-iam');
const logs = require('aws-cdk-lib/aws-logs');

/** IAM and Batch names allow letters, digits, hyphens and underscores only. */
function sanitize(value) {
  return value.replace(/[^A-Za-z0-9-_]/g, '-');
}

function limited(value, length) {
  return value.slice(0, length);
}

function prefixOf(project) {
  return sanitize(project.namespace + '-' + project.name);
}

function nameOf(project, id) {
  return limited(prefixOf(project) + '-' + sanitize(id), 64);
}

/**
 * Provision the managed guardrail for one job, and nothing when the spec leaves it to its
 * operator. The HCL module spells the same two resources.
 */
function addGuardrail(scope, context, id, service, role) {
  if (!(service.guardrailEngines || []).includes('bedrock')) return undefined;

  const policy = (context.guardrails || {})[id];
  if (!policy) return undefined;

  const props = {
    name: (nameOf(context.project, id) + '-guardrail').slice(0, 50),
    description: policy.message,
    blockedInputMessaging: policy.message,
    blockedOutputsMessaging: policy.message,
  };

  if (policy.content.length > 0) {
    props.contentPolicyConfig = {
      filtersConfig: policy.content.map((filter) => ({
        type: filter.type,
        inputStrength: filter.strength,
        outputStrength: filter.strength,
      })),
    };
  }

  if (policy.topics.length > 0) {
    props.topicPolicyConfig = {
      topicsConfig: policy.topics.map((topic) => ({
        name: topic.name,
        definition: topic.definition,
        type: 'DENY',
      })),
    };
  }

  if (policy.words.length > 0) {
    props.wordPolicyConfig = {
      wordsConfig: policy.words.map((text) => ({ text: text })),
    };
  }

  if (policy.pii.length > 0) {
    props.sensitiveInformationPolicyConfig = {
      piiEntitiesConfig: policy.pii.map((entity) => ({
        type: entity.type,
        action: entity.action,
      })),
    };
  }

  const guardrail = new bedrock.CfnGuardrail(scope, id + 'Guardrail', props);

  const version = new bedrock.CfnGuardrailVersion(scope, id + 'GuardrailVersion', {
    guardrailIdentifier: guardrail.attrGuardrailId,
    description: 'Published by aid infra gen from the spec.',
  });

  role.addToPolicy(
    new iam.PolicyStatement({
      actions: ['bedrock:ApplyGuardrail'],
      resources: [guardrail.attrGuardrailArn],
    }),
  );

  return { guardrail: guardrail, version: version };
}

function addBatch(scope, context, inputs) {
  const jobs = {};
  for (const id of Object.keys(context.services)) {
    if (context.services[id].target === 'batch') jobs[id] = context.services[id];
  }

  const result = { queue: undefined, jobDefinitions: {}, logGroups: {} };
  const ids = Object.keys(jobs);
  if (ids.length === 0) return result;

  const images = inputs.images || {};
  const secretArns = inputs.secretArns || {};
  const sizing = inputs.batchSizing || {};
  const subnets = inputs.subnetIds || [];
  const securityGroups = inputs.securityGroupIds || [];

  for (const id of ids) {
    const service = jobs[id];
    if (!images[id]) {
      throw new Error(
        'No images entry for "' + id + '". A job definition must name the image it runs.',
      );
    }
    if (!service.pipeline) {
      throw new Error(
        'Deployment "' + id + '" targets batch but names no pipeline. Set ' +
          'deployments.' + id + '.pipeline to the pipeline the job runs.',
      );
    }
    for (const variable of service.env) {
      if (variable.secret && !secretArns[variable.name]) {
        throw new Error(
          'Deployment "' + id + '" references a secret with no secretArns entry. ' +
            'Add name -> ARN for every secret it declares.',
        );
      }
    }
  }

  // Fargate has nowhere to run without a subnet, so the refusal is the first thing a
  // caller reads rather than a stack that fails part-way through an apply.
  if (subnets.length === 0) {
    throw new Error(
      'No subnetIds were supplied. Fargate has nowhere to run a task without at least one ' +
        'subnet; name the subnets this job may use.',
    );
  }

  // Every job shares these three roles. Batch assumes the service role, ECS assumes the
  // execution role to pull the image and resolve secrets, and the job assumes the task
  // role to call Bedrock.
  const serviceRole = new iam.Role(scope, 'BatchServiceRole', {
    roleName: limited(prefixOf(context.project), 45) + '-batch-service',
    assumedBy: new iam.ServicePrincipal('batch.amazonaws.com'),
    managedPolicies: [
      iam.ManagedPolicy.fromAwsManagedPolicyName('service-role/AWSBatchServiceRole'),
    ],
  });

  const executionRole = new iam.Role(scope, 'BatchExecutionRole', {
    roleName: limited(prefixOf(context.project), 42) + '-batch-execution',
    assumedBy: new iam.ServicePrincipal('ecs-tasks.amazonaws.com'),
    managedPolicies: [
      iam.ManagedPolicy.fromAwsManagedPolicyName(
        'service-role/AmazonECSTaskExecutionRolePolicy',
      ),
    ],
  });

  const taskRole = new iam.Role(scope, 'BatchTaskRole', {
    roleName: limited(prefixOf(context.project), 46) + '-batch-task',
    assumedBy: new iam.ServicePrincipal('ecs-tasks.amazonaws.com'),
  });

  const streams = ids.some((id) => jobs[id].streaming);
  if (ids.some((id) => (jobs[id].providers || []).includes('bedrock'))) {
    taskRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ['bedrock:InvokeModel'].concat(
          streams ? ['bedrock:InvokeModelWithResponseStream'] : [],
        ),
        resources: [
          'arn:' + cdk.Aws.PARTITION + ':bedrock:*::foundation-model/*',
          'arn:' + cdk.Aws.PARTITION + ':bedrock:*:' + cdk.Aws.ACCOUNT_ID + ':inference-profile/*',
        ],
      }),
    );
  }

  if (Object.keys(secretArns).length > 0) {
    executionRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ['secretsmanager:GetSecretValue'],
        resources: Object.keys(secretArns).map((name) => secretArns[name]),
      }),
    );
  }

  // Retrieve is the only call a managed base is used for. The id and ARN arrive in
  // `inputs` rather than the context: the context is written before anything is applied,
  // so it can only say which base the spec declared. A base with no input entry does not
  // exist yet, and a policy with an empty resource is invalid rather than merely empty.
  const providedBases = inputs.knowledgeBases || {};
  const declaredBases = context.knowledgeBases || {};
  const bases = Object.keys(declaredBases)
    .filter((baseId) => declaredBases[baseId].engine === 'aws-bedrock' && providedBases[baseId])
    .map((baseId) =>
      Object.assign({}, declaredBases[baseId], {
        id: providedBases[baseId].id,
        arn: providedBases[baseId].arn,
      }),
    )
    .filter((base) => base.id && base.arn);

  if (bases.length > 0) {
    taskRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ['bedrock:Retrieve'],
        resources: bases.map((base) => base.arn),
      }),
    );
  }

  const compute = new batch.CfnComputeEnvironment(scope, 'BatchComputeEnvironment', {
    computeEnvironmentName: limited(prefixOf(context.project), 50) + '-batch',
    type: 'MANAGED',
    state: 'ENABLED',
    serviceRole: serviceRole.roleArn,
    computeResources: {
      type: 'FARGATE',
      maxvCpus: inputs.maxVcpus || 16,
      subnets: subnets,
      securityGroupIds: securityGroups,
    },
  });

  const queue = new batch.CfnJobQueue(scope, 'BatchJobQueue', {
    jobQueueName: limited(prefixOf(context.project), 50) + '-batch',
    state: 'ENABLED',
    priority: 1,
    computeEnvironmentOrder: [
      { order: 1, computeEnvironment: compute.attrComputeEnvironmentArn },
    ],
  });

  for (const id of ids) {
    const service = jobs[id];
    const size = sizing[id] || {};
    const name = nameOf(context.project, id);
    const group = new logs.CfnLogGroup(scope, id + 'BatchLogGroup', {
      logGroupName: '/aws/batch/' + name,
      retentionInDays: inputs.logRetentionDays || 30,
    });

    const variables = [];
    if ((service.providers || []).includes('bedrock')) {
      variables.push({ name: 'AWS_REGION', value: inputs.bedrockRegion || cdk.Aws.REGION });
    }

    const managed = addGuardrail(scope, context, id, service, taskRole);
    if (managed) {
      variables.push({ name: 'BEDROCK_GUARDRAIL_ID', value: managed.guardrail.attrGuardrailId });
      variables.push({
        name: 'BEDROCK_GUARDRAIL_VERSION',
        value: managed.version.attrVersion,
      });
    }

    for (const base of bases) {
      const bound = (base.retrievers || []).some((retriever) =>
        (service.ingest || []).includes(retriever),
      );
      if (bound) variables.push({ name: base.envName, value: base.id });
    }

    const secrets = [];
    for (const variable of service.env) {
      if (variable.secret) {
        secrets.push({ name: variable.name, valueFrom: secretArns[variable.name] });
      } else if (variable.value !== undefined) {
        variables.push({ name: variable.name, value: variable.value });
      }
    }

    result.logGroups[id] = group.ref;
    result.jobDefinitions[id] = new batch.CfnJobDefinition(scope, id + 'BatchJobDefinition', {
      jobDefinitionName: name,
      type: 'container',
      platformCapabilities: ['FARGATE'],
      retryStrategy: { attempts: size.attempts || 1 },
      timeout: { attemptDurationSeconds: size.timeoutSeconds || 3600 },
      containerProperties: {
        image: images[id],
        command: ['python', '-m', 'app.generated.batch', service.pipeline],
        jobRoleArn: taskRole.roleArn,
        executionRoleArn: executionRole.roleArn,
        resourceRequirements: [
          { type: 'VCPU', value: String(size.vcpus || 1) },
          { type: 'MEMORY', value: String(size.memoryMb || 2048) },
        ],
        environment: variables,
        secrets: secrets,
        networkConfiguration: {
          assignPublicIp: inputs.assignPublicIp ? 'ENABLED' : 'DISABLED',
        },
        fargatePlatformConfiguration: { platformVersion: 'LATEST' },
        logConfiguration: {
          logDriver: 'awslogs',
          options: {
            'awslogs-group': group.ref,
            'awslogs-region': cdk.Aws.REGION,
            'awslogs-stream-prefix': 'batch',
          },
        },
      },
    });
  }

  result.queue = queue;
  return result;
}

module.exports = { addBatch: addBatch };
